def _write_text(path, text):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8", newline="\n") as handle:
        handle.write(text)


def _write_json(path, value):
    _write_text(path, json.dumps(value, indent=2, ensure_ascii=False) + "\n")


def _css_name(role):
    return role.replace(".", "-").replace("_", "-")


def _css_value(role, value):
    if isinstance(value, (int, float)):
        if role.startswith("motion."):
            return "%gms" % value
        if role == "typography.label.weight" or role.endswith(".opacity"):
            return "%g" % value
        return "%gpx" % value
    if role.startswith("typography."):
        return '"%s", system-ui, sans-serif' % str(value).replace('"', "")
    return str(value)


def emit_tokens(resolved):
    lines = [
        "/* GENERATED by BrandBuilder gen_web_react.py. Framework-neutral semantic interface tokens. */",
        ":root {",
    ]
    for role, value in sorted(resolved["roles_by_theme"]["dark"].items()):
        lines.append("  --bb-%s: %s;" % (_css_name(role), _css_value(role, value)))
    lines += ["}", "", ".bb-light {"]
    for role, value in sorted(resolved["roles_by_theme"]["light"].items()):
        lines.append("  --bb-%s: %s;" % (_css_name(role), _css_value(role, value)))
    lines += ["}", ""]
    return "\n".join(lines)


