ENVIRONMENT_TSX = '''"use client";
import { useEffect } from "react";

function mobileLayoutResizeCanBeIme() { const navigatorWithHints = navigator as Navigator & { userAgentData?: { mobile?: boolean } }; return navigatorWithHints.userAgentData?.mobile ?? (/Android|iPhone|iPad|iPod/i.test(navigator.userAgent) || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1)); }
export function measureImeBlockEnd(viewport: VisualViewport | null = window.visualViewport, layoutBaseline = window.innerHeight) { const visualViewportInset = viewport ? window.innerHeight - viewport.height - viewport.offsetTop : 0; const resizedLayoutInset = layoutBaseline - window.innerHeight; return Math.max(0, visualViewportInset, resizedLayoutInset); }
export function AppFrameEnvironmentBridge({ imeBlockEnd = 0 }: { imeBlockEnd?: number }) { useEffect(() => { const root = document.documentElement; const viewport = window.visualViewport; const layoutHeights = new Map<string, number>(); const mobileLayoutResize = mobileLayoutResizeCanBeIme(); const orientation = () => window.innerWidth > window.innerHeight ? "landscape" : "portrait"; const update = () => { const key = orientation(); const previous = layoutHeights.get(key) ?? window.innerHeight; const editable = document.activeElement instanceof HTMLInputElement || document.activeElement instanceof HTMLTextAreaElement || (document.activeElement instanceof HTMLElement && document.activeElement.isContentEditable); const baseline = mobileLayoutResize ? (editable ? previous : Math.max(previous, window.innerHeight)) : window.innerHeight; layoutHeights.set(key, baseline); const height = viewport?.height ?? window.innerHeight; const offset = viewport?.offsetTop ?? 0; root.dataset.bbAppFrameMounted = "true"; root.style.setProperty("--bb-visual-viewport-height", `${height}px`); root.style.setProperty("--bb-visual-viewport-offset-block-start", `${offset}px`); root.style.setProperty("--bb-ime-block-end", `${Math.max(imeBlockEnd, measureImeBlockEnd(viewport, baseline))}px`); }; update(); viewport?.addEventListener("resize", update); viewport?.addEventListener("scroll", update); window.addEventListener("resize", update); return () => { viewport?.removeEventListener("resize", update); viewport?.removeEventListener("scroll", update); window.removeEventListener("resize", update); delete root.dataset.bbAppFrameMounted; root.style.removeProperty("--bb-visual-viewport-height"); root.style.removeProperty("--bb-visual-viewport-offset-block-start"); root.style.removeProperty("--bb-ime-block-end"); }; }, [imeBlockEnd]); return null; }
'''


